-- Additional spoken lines; the game controls its emote animation and text.
local _, addon = ...
local texts = addon.localeData.enUS.generalTexts
texts.INCOMING = { gruppe = { "Incoming! And not the friendly kind!", "They're closing in. Get ready." }, ziel = { "%s: They're closing in. Get ready.", "%s: Incoming! And not the friendly kind!" } }
texts.INSULT = { gruppe = { "Some words do not deserve a polite reply.", "Your arrogance outweighs your wisdom." }, ziel = { "%s: Your arrogance outweighs your wisdom.", "%s: Some words do not deserve a polite reply." } }
texts.INTRODUCE = { gruppe = { "Allow me to introduce myself.", "A good beginning starts with a name." }, ziel = { "%s: A good beginning starts with a name.", "%s: Allow me to introduce myself." } }
texts.JK = { gruppe = { "Only joking! Put the weapons away.", "A little humour may look dangerous." }, ziel = { "%s: A little humour may look dangerous.", "%s: Only joking! Put the weapons away." } }
texts.KISS = { gruppe = { "Sometimes a kiss says more than any speech.", "Life is too short for forgotten affection." }, ziel = { "%s: Life is too short for forgotten affection.", "%s: Sometimes a kiss says more than any speech." } }
texts.KNUCKLES = { gruppe = { "These hands are ready. How about yours?", "Let's hope this will be a fair fight." }, ziel = { "%s: Let's hope this will be a fair fight.", "%s: These hands are ready. How about yours?" } }
texts.LAVISH = { gruppe = { "Compliments are not a thing to be rationed.", "That entrance deserves a royal tribute." }, ziel = { "%s: That entrance deserves a royal tribute.", "%s: Compliments are not a thing to be rationed." } }
texts.LICK = { gruppe = { "The flavour is... unusual.", "Perhaps I should have asked first." }, ziel = { "%s: Perhaps I should have asked first.", "%s: The flavour is... unusual." } }
texts.LISTEN = { gruppe = { "One moment. I can hear something.", "Quiet voices often tell the greater tale." }, ziel = { "%s: Quiet voices often tell the greater tale.", "%s: One moment. I can hear something." } }
texts.LOST = { gruppe = { "That turning wasn't on my map.", "We're not lost, merely travelling unexpectedly." }, ziel = { "%s: We're not lost, merely travelling unexpectedly.", "%s: That turning wasn't on my map." } }
texts.MASSAGE = { gruppe = { "A long march demands its price.", "These shoulders are desperate for relief." }, ziel = { "%s: These shoulders are desperate for relief.", "%s: A long march demands its price." } }
texts.MOAN = { gruppe = { "That was less pleasant than I hoped.", "We are allowed to complain once in a while, aren't we?" }, ziel = { "%s: We are allowed to complain once in a while, aren't we?", "%s: That was less pleasant than I hoped." } }
texts.MOCK = { gruppe = { "Truly impressive. Almost.", "Perhaps you should practise that a little more." }, ziel = { "%s: Perhaps you should practise that a little more.", "%s: Truly impressive. Almost." } }
texts.MOON = { gruppe = { "Some people won't forget that in a hurry.", "I call it an unconventional greeting." }, ziel = { "%s: I call it an unconventional greeting.", "%s: Some people won't forget that in a hurry." } }
texts.MOURN = { gruppe = { "A life is more than its final hour.", "May memory outlast the grief." }, ziel = { "%s: May memory outlast the grief.", "%s: A life is more than its final hour." } }
texts.NO = { gruppe = { "No. And that is final.", "Not every proposal deserves agreement." }, ziel = { "%s: Not every proposal deserves agreement.", "%s: No. And that is final." } }
texts.NOSEPICK = { gruppe = { "Some investigations are better carried out in private.", "That was not terribly dignified." }, ziel = { "%s: That was not terribly dignified.", "%s: Some investigations are better carried out in private." } }
texts.OOM = { gruppe = { "My magical reserves are completely exhausted!", "A sip of water won't fix this on its own." }, ziel = { "%s: A sip of water won't fix this on its own.", "%s: My magical reserves are completely exhausted!" } }
texts.OPENFIRE = { gruppe = { "On my mark! Open fire!", "Take aim and hold the line." }, ziel = { "%s: Take aim and hold the line.", "%s: On my mark! Open fire!" } }
texts.PANIC = { gruppe = { "That was not part of the plan!", "Why is everyone suddenly running everywhere?" }, ziel = { "%s: Why is everyone suddenly running everywhere?", "%s: That was not part of the plan!" } }
texts.PARTY = { gruppe = { "Tonight the adventure can wait outside.", "Music and friends are reason enough to celebrate." }, ziel = { "%s: Music and friends are reason enough to celebrate.", "%s: Tonight the adventure can wait outside." } }
texts.PAT = { gruppe = { "Well done. That wasn't easy.", "Sometimes courage simply deserves recognition." }, ziel = { "%s: Sometimes courage simply deserves recognition.", "%s: Well done. That wasn't easy." } }
texts.PEER = { gruppe = { "Something is moving back there.", "I'll take a closer look before deciding." }, ziel = { "%s: I'll take a closer look before deciding.", "%s: Something is moving back there." } }
texts.PEST = { gruppe = { "A little nuisance keeps the gathering awake.", "Perhaps I should annoy someone a little less." }, ziel = { "%s: Perhaps I should annoy someone a little less.", "%s: A little nuisance keeps the gathering awake." } }
texts.PICK = { gruppe = { "Some things yield only to patience.", "A clever touch saves much effort." }, ziel = { "%s: A clever touch saves much effort.", "%s: Some things yield only to patience." } }
texts.PITY = { gruppe = { "Nobody should have had to endure that.", "My sympathy goes to everyone involved." }, ziel = { "%s: My sympathy goes to everyone involved.", "%s: Nobody should have had to endure that." } }
texts.PIZZA = { gruppe = { "A hot meal can rescue an evening.", "Anyone wanting a slice should speak now." }, ziel = { "%s: Anyone wanting a slice should speak now.", "%s: A hot meal can rescue an evening." } }
texts.PLEAD = { gruppe = { "Please, hear me out.", "More is at stake than you realize." }, ziel = { "%s: More is at stake than you realize.", "%s: Please, hear me out." } }
texts.POKE = { gruppe = { "Are you still among the living?", "A gentle nudge should be enough." }, ziel = { "%s: A gentle nudge should be enough.", "%s: Are you still among the living?" } }
texts.PONDER = { gruppe = { "That deserves careful consideration.", "Not every answer can be found at once." }, ziel = { "%s: Not every answer can be found at once.", "%s: That deserves careful consideration." } }
texts.POUNCE = { gruppe = { "Surprise! Your turn now.", "The best plan often starts with a leap." }, ziel = { "%s: The best plan often starts with a leap.", "%s: Surprise! Your turn now." } }
texts.PRAISE = { gruppe = { "That deserves sincere praise.", "Great deeds need no grand speeches." }, ziel = { "%s: Great deeds need no grand speeches.", "%s: That deserves sincere praise." } }
texts.PRAY = { gruppe = { "May a little wisdom guide us today.", "Even in a storm there is room for hope." }, ziel = { "%s: Even in a storm there is room for hope.", "%s: May a little wisdom guide us today." } }
texts.PUZZLED = { gruppe = { "There is a piece of this puzzle missing.", "The answer is probably right in front of us." }, ziel = { "%s: The answer is probably right in front of us.", "%s: There is a piece of this puzzle missing." } }
texts.QUESTION = { gruppe = { "May I ask something about that?", "A good question is half an answer." }, ziel = { "%s: A good question is half an answer.", "%s: May I ask something about that?" } }
